scene('alcohol-wash','Wash retained precipitate','wash','Wash the retained precipitate using the same alcohol used for both stock preparations.', [('Retained fraction','Washed solid precipitate.'),('Separate routes','Each solvent route remains separate; no alcohol mixture is implied.'),('Unreported','Wash volume, cycle count and wash-separation details.')],wash='route')
scene('ambient-dry','Room-temperature drying','dry','Dry the alcohol-washed precipitate at room temperature for 24 h before the acetone wash.', [('Order','Alcohol wash → 24 h ambient drying → acetone wash.'),('Unreported','Numerical temperature, atmosphere and drying apparatus. A vacuum oven is not asserted.')])
