scene('tem-acquire','HRTEM and selected-area diffraction','tem','Use JEOL 2100 HRTEM for the separately assigned Figure 1 specimens and retain the original SAED panels.', [('Samples','Ethanol, 1-propanol and 1-butanol as-prepared specimens; calcined 1-butanol comparison.'),('Local versus bulk','Local CeO2 fringes/SAED do not establish pure whole as-prepared composition.'),('Unreported','Grid preparation, accelerating voltage and dose/exposure.')])
