  k=r['record_id']+'--'+o['id'];cfg[k]=c
  bindings.append({'scene_id':k,'record_id':r['record_id'],'record_path':str(C/(r['record_id']+'.json')),'record_sha256':sha(C/(r['record_id']+'.json')),'operation_id':o['id'],'operation_pointer':c['operation_pointer'],'inputs':o['inputs'],'outputs':o['outputs'],'retained_fraction':o['retained_fraction'],'source_evidence':o['evidence'],'supplemental_source_fact_ids':c['source_context_fact_ids'],'supplemental_source_evidence':ev,'canonical_description':o['description'],'human_prose':c['prose'],'art':c['art'],'option_pointers':[]})
